package org.sleepwell.app;

import androidx.activity.ComponentActivity;
import androidx.activity.OnBackPressedCallback;

import android.app.*;
import android.os.*;
import android.widget.*;
import java.util.*;

/** Explicit opt-in folder ZIP save and independent version review; never starts an upload on open. */
public final class CloudAudioActivity extends ComponentActivity {
    private CloudAudioJob job;private CloudAudioJob.State drawn;private AutoCloudAudio.State automatic;private final Handler main=new Handler(Looper.getMainLooper());private boolean resumed,acknowledged;private String reviewedFingerprint="",selectedVersion="";private Dialog dialog;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);job=CloudAudioJob.get(this,Records.factory);if(saved!=null){acknowledged=saved.getBoolean("acknowledged");reviewedFingerprint=saved.getString("fingerprint","");selectedVersion=saved.getString("version","");}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){back();}});render();}
    private void render(){drawn=job.state();automatic=AutoCloudAudio.state;LibraryAudioArchive.Plan plan=drawn.plan;String identity=plan==null?"":plan.metadata.fingerprint+"|"+(drawn.destination==null?"":drawn.destination.tree+"|"+drawn.destination.revision);if(!identity.equals(reviewedFingerprint)){reviewedFingerprint=identity;acknowledged=false;}LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,selectedVersion.isEmpty()?"Audio folder backup":"Audio backup version",this::back);Design.space(body,14);if(!selectedVersion.isEmpty()){version(body);return;}Design.text(body,"Manual audio ZIP",23,600,Design.INK);Design.text(body,"Creates one new version in your remembered folder. Automatic metadata backup stays separate and never includes audio.",13,400,Design.MUTED);Design.space(body,12);if(drawn.destination!=null)PlanActivity.detail(body,"cloud","Selected folder",drawn.destination.label,drawn.destination.tree.isEmpty()?"Not selected":"Remembered",null);if(plan!=null){PlanActivity.detail(body,"wave","Complete WAV recordings",null,""+plan.audio.size(),null);PlanActivity.detail(body,"moon","Nights with sound-library data",null,""+plan.metadata.records.size(),null);PlanActivity.detail(body,"file","Sound events and labels",null,""+plan.metadata.events.size(),null);PlanActivity.detail(body,"upload","Uncompressed audio",null,size(plan.bytes),null);Design.space(body,10);Design.text(body,"Includes every saved raw recording, even audio outside edited sleep times, and a complete metadata backup of alarms, records, notes and sound labels. It can contain voices and other private sounds. App settings and account credentials are excluded.",13,500,Design.BROWN);Design.text(body,"All-or-error limits: 999 recordings, 20,000 events, 2,000 audio-source nights, 256 MiB audio and existing metadata limits. Nothing is silently omitted.",12,400,Design.MUTED);Switch consent=Design.toggle(body,"Include my complete private recordings","I reviewed the counts and folder access above.",acknowledged,on->acknowledged=on);consent.setEnabled(!drawn.busy());}
        automatic(body,plan);Design.space(body,10);if(!drawn.message.isEmpty())Design.text(body,drawn.message,14,500,Design.BROWN);Design.text(body,"Keep the app running while saving. Android or your provider can interrupt it; reopening never retries an upload. Read-back verifies provider bytes, not remote-cloud completion.",12,400,Design.MUTED);Design.space(body,18);Design.text(body,"Audio version history",18,600,Design.INK);Design.text(body,"Last 20 audio versions from this installation. Older provider files are kept. This history is separate from JSON versions.",12,400,Design.MUTED);if(drawn.history.isEmpty())Design.text(body,"No audio versions saved yet.",13,400,Design.MUTED);for(CloudAudioVersions.Entry entry:drawn.history){String when=java.time.Instant.ofEpochMilli(entry.time).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("d MMM · HH:mm",Locale.getDefault()));PlanActivity.detail(body,"file",when,entry.clips+" recordings · "+entry.status.toLowerCase(Locale.ROOT),entry.verified()?"Review":"Details",()->{selectedVersion=entry.id;render();});Design.line(body);}LinearLayout footer=RecordUi.footer(body);if(drawn.writing())Design.button(footer,"Cancel audio save",false,()->{job.cancel();render();});else if(drawn.phase!=CloudAudioJob.Phase.CLEANUP){Design.button(footer,"Save new audio ZIP to folder",true,()->{if(!acknowledged){SleepPicker.message(this,"Review private content","Confirm the complete private recordings and selected folder before saving.");return;}job.save();acknowledged=false;render();}).setEnabled(!drawn.busy()&&plan!=null&&!plan.audio.isEmpty()&&drawn.destination!=null&&!drawn.destination.tree.isEmpty());Design.button(footer,"Refresh library review",false,()->{acknowledged=false;job.refresh();render();}).setEnabled(!drawn.busy());}else Design.text(footer,"Further folder backups are blocked until provider cleanup is confirmed by a process restart.",13,500,Design.BROWN);}
    private void automatic(LinearLayout body,LibraryAudioArchive.Plan plan){Design.space(body,16);Design.line(body);Switch option=Design.toggle(body,"Automatic whole-library audio","Separate opt-in · charging and unmetered network",automatic.enabled,on->{if(on)confirmAutomatic(plan);else{AutoCloudAudio.configure(this,false,null,null);render();}});option.setEnabled(automatic.enabled||!automatic.busy&&!drawn.busy()&&plan!=null&&drawn.destination!=null&&!drawn.destination.tree.isEmpty()&&drawn.phase!=CloudAudioJob.Phase.CLEANUP);Design.text(body,automatic.message,13,500,Design.BROWN);if(automatic.pending>0||automatic.attention>0)Design.text(body,automatic.pending+" pending · "+automatic.attention+" need review",12,500,Design.MUTED);if(automatic.enabled&&automatic.pending>0)Design.button(body,"Request Android scheduling",false,()->AutoCloudAudio.reschedule(this)).setEnabled(!automatic.busy);Design.text(body,"After a future successfully recorded night, saves every existing and future recording plus full metadata as a new whole-library ZIP. Only successfully ended tracking creates requests; enabling, opening, manual edits and imports do not. Android may defer or stop it; queued requests expire after seven days. Uncertain writes are never automatically replayed. This does not enable audio recording.",12,400,Design.MUTED);Design.line(body);}
    private void confirmAutomatic(LibraryAudioArchive.Plan plan){if(plan==null||drawn.destination==null){render();return;}CloudBackupSettings.Destination destination=drawn.destination;if(dialog!=null)dialog.dismiss();dialog=new AlertDialog.Builder(this).setTitle("Automatically copy all private audio?").setMessage("Current library: "+plan.audio.size()+" complete recordings · "+size(plan.bytes)+" of raw audio.\n\nEvery version includes the entire library, including voices or audio outside edited sleep times, plus all record and alarm metadata. Future recordings are included too.\n\nAfter future successfully recorded nights only, while charging on an unmetered network. Nothing uploads when enabled. Existing limits still apply; failures never silently omit recordings. Saved provider files stay when you turn this off.").setNegativeButton("Keep audio automatic backup off",(d,w)->render()).setPositiveButton("Enable whole-library audio",(d,w)->{AutoCloudAudio.configure(this,true,plan,destination);render();}).create();dialog.setOnCancelListener(d->render());dialog.show();ReportDialogs.style((AlertDialog)dialog);}
    private void version(LinearLayout body){CloudAudioVersions.Entry selected=null;for(CloudAudioVersions.Entry entry:drawn.history)if(entry.id.equals(selectedVersion))selected=entry;if(selected==null){Design.text(body,"This version is no longer in the local 20-version history. Provider files have not been deleted.",14,500,Design.MUTED);Design.button(body,"Back to library review",true,()->{selectedVersion="";render();});return;}CloudAudioVersions.Entry entry=selected;Design.text(body,entry.name,17,600,Design.INK);Design.space(body,12);PlanActivity.detail(body,"wave","Complete recordings",null,""+entry.clips,null);PlanActivity.detail(body,"file","Sound events",null,""+entry.events,null);PlanActivity.detail(body,"upload","Audio / complete ZIP",size(entry.audioBytes),size(entry.zipBytes),null);Design.text(body,entry.message,14,500,Design.BROWN);Design.space(body,10);if(entry.verified())Design.text(body,"SHA-256\n"+entry.sha,11,400,Design.MUTED);else Design.text(body,"This version is not verified. A complete or partial file may remain in the provider folder; it is never automatically retried or removed.",13,400,Design.MUTED);boolean current=drawn.destination!=null&&entry.tree.equals(drawn.destination.tree);if(!current)Design.text(body,"Re-select this version’s original folder in Cloud backup before opening it. Remembered destination changes may release old folder access.",13,500,Design.MUTED);Design.text(body,"Opening a verified version only validates and reviews its contents. Actual restore requires a second explicit replacement confirmation; imported alarms stay off.",13,400,Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(entry.verified())Design.button(footer,"Review audio restore…",true,()->startActivity(RecordUi.intent(this,LibraryAudioImportActivity.class).putExtra("document",entry.uri).putExtra("expectedSha",entry.sha))).setEnabled(current&&!drawn.writing()&&drawn.phase!=CloudAudioJob.Phase.CLEANUP);Design.button(footer,"Back to library review",false,()->{selectedVersion="";render();});}
    private String size(long bytes){return android.text.format.Formatter.formatShortFileSize(this,bytes);}
    private final Runnable watch=new Runnable(){public void run(){if(!resumed)return;if(job.state()!=drawn||AutoCloudAudio.state!=automatic)render();main.postDelayed(this,150);}};
    @Override protected void onResume(){super.onResume();resumed=true;AutoCloudAudio.inspect(this);if(!job.state().busy()&&job.state().phase!=CloudAudioJob.Phase.CLEANUP)job.refresh();render();main.post(watch);}@Override protected void onPause(){resumed=false;main.removeCallbacks(watch);super.onPause();}
    private void back(){if(!selectedVersion.isEmpty()){selectedVersion="";render();return;}if(job.state().writing()){if(dialog!=null)dialog.dismiss();dialog=new AlertDialog.Builder(this).setTitle("Audio save is still running").setMessage("Leaving keeps this explicitly started save running while the process remains alive. Cancel waits for provider cleanup; a partial file may remain.").setPositiveButton("Keep saving and leave",(d,w)->finish()).setNegativeButton("Cancel audio save",(d,w)->{job.cancel();render();}).create();dialog.show();ReportDialogs.style((AlertDialog)dialog);}else finish();}
    @Override public void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putBoolean("acknowledged",acknowledged);saved.putString("fingerprint",reviewedFingerprint);saved.putString("version",selectedVersion);}@Override protected void onDestroy(){main.removeCallbacks(watch);if(dialog!=null)dialog.dismiss();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
